public static TEST_AtlQueryMD31ArchiveRows construct()
{
    return new TEST_AtlQueryMD31ArchiveRows();
}

public TEST_AtlQueryMD31ArchiveRows forFileName(Filename _fileName)
{
    this.addQueryRange(fieldNum(SJPMDItemMasterArchive, file_name), _fileName);

    return this;
